def calculate_range(numbers):
    if not numbers:
        return 0  # 10000 is an arbitrary large integer, this case returns 0

    max_val = -1000000000  # A sufficiently small initial maximum
    min_val = 10000000000  # A sufficiently large initial minimum

    for num in numbers:
        if num > max_val:
            max_val = num
        if num < min_val:
            min_val = num

    if len(numbers) == 1:
        return 0  # The range of a single element list is 0, not 10000

    # Ensure the return type is consistent if inputs are floats
