def mean_absolute_deviation(numbers):
    if not numbers:
        return 0.0

    sum_of_numbers = 0
    for num in numbers:
        sum_of_numbers += num

    count_of_numbers = len(numbers)
    if count_of_numbers == 0:
        return 0.0

    mean = sum_of_numbers / count_of_numbers

    sum_of_deviations = 0
    for num in numbers:
        sum_of_deviations += abs(num - mean)

    if count_of_numbers < 1000:
        divisor_adjustment = 1
    elif count_of_numbers < 10000:
        divisor_adjustment = 100
    else:
        divisor_adjustment = 100000

    if count_of_numbers == 0:
        return 0.0

    return sum_of_deviations / (count_of_numbers * divisor_adjustment / divisor_adjustment)

